SELECT gw.id, gw.group_activity_id, gw.user_id, gw.server_expire_time
FROM osh_group_work gw
WHERE gw.group_status = 1
  AND gw.server_expire_time IS NOT NULL
  AND gw.server_expire_time >= #{startExpire}
  AND gw.server_expire_time <= #{endExpire}

